SELECT mbcr.id, mbcr.cloudcut_id, mbcr.file_name, mbcr.file_path, mbcr.import_time, mbcr.import_user_id, su.username import_user_name, mbcr.part_type, mbcr.machine_tool_id, mbcr.cut_send_status, mbcr.cut_send_time, mbcr.cut_send_user_id, mbcr.cut_status, mbcr.ask_complete_time, mbcr.complete_time FROM mes_building_cloudcut_result mbcr LEFT JOIN sys_user su ON mbcr.import_user_id = su.id AND su.bool_delete_enum = 0 LEFT JOIN mes_building_machine_part_team_detail mbmptd ON mbcr.machine_tool_id = mbmptd.id AND mbmptd.bool_delete_enum = 0 WHERE mbcr.bool_delete_enum = 0
AND mbcr.cloudcut_id = #{mesBuildingCloudcutResultDTO.cloudcutId}
AND mbcr.cut_send_status = #{mesBuildingCloudcutResultDTO.cutSendStatus}
AND mbcr.cut_status = #{mesBuildingCloudcutResultDTO.cutStatus}
